import pulp

# Data
products = ['I', 'II', 'III']
quarters = [1, 2, 3, 4]

D = {
    ('I', 1): 1500, ('I', 2): 1000, ('I', 3): 2000, ('I', 4): 1200,
    ('II', 1): 1500, ('II', 2): 1500, ('II', 3): 1200, ('II', 4): 1500,
    ('III', 1): 1000, ('III', 2): 2000, ('III', 3): 1500, ('III', 4): 2500
}

p = {'I': 2, 'II': 4, 'III': 3}
C = {t: 15000 for t in quarters}
h = 5
b = {'I': 20, 'II': 20, 'III': 10}
Inv0 = {i: 0 for i in products}
B0 = {i: 0 for i in products}
Inv_final = {i: 150 for i in products}

prob = pulp.LpProblem("Production_Planning", pulp.LpMinimize)

# Decision variables
x = pulp.LpVariable.dicts("x", [(i, t) for i in products for t in quarters], lowBound=0)
Inv = pulp.LpVariable.dicts("Inv", [(i, t) for i in products for t in [0] + quarters], lowBound=0)
B = pulp.LpVariable.dicts("B", [(i, t) for i in products for t in [0] + quarters], lowBound=0)

# Objective function
prob += (
    5 * pulp.lpSum(Inv[i][t] for i in products for t in quarters)
    + 20 * pulp.lpSum(B['I'][t] + B['II'][t] for t in quarters)
    + 10 * pulp.lpSum(B['III'][t] for t in quarters)
)

# Constraints
# (a) Inventory balance
for i in products:
    for t in quarters:
        prob += Inv[i][t-1] + x[i][t] == D[i, t] + Inv[i][t] - B[i][t] + B[i][t-1]

# (b) Initial conditions
for i in products:
    prob += Inv[i][0] == Inv0[i]
    prob += B[i][0] == B0[i]

# (c) Capacity
for t in quarters:
    prob += 2 * x['I'][t] + 4 * x['II'][t] + 3 * x['III'][t] <= C[t]

# (d) Q2 production ban for product I
prob += x['I'][2] == 0

# (e) Final inventory requirement
for i in products:
    prob += Inv[i][4] == Inv_final[i]

prob.solve(pulp.PULP_CBC_CMD(msg=False, timeLimit=60))
print(f"STATUS={pulp.LpStatus[prob.status]} OBJECTIVE={pulp.value(prob.objective)}")

