import pulp

# Data
D = ['D', 'N']
J = [1, 2, 3]
K = [1, 2, 3, 4, 5, 6]

C = [(1,1),(1,2),(2,2),(2,3),(3,1),(3,3),(4,1),(4,3),(5,2),(5,3),(6,3)]
P = [('D',1),('D',2),('N',1),('N',2),('N',3)]

a = {k: 1500 for k in K}
dem = {('D',1): 1000, ('D',2): 2000, ('N',1): 2000, ('N',2): 1000, ('N',3): 1000}
pm = {1:1, 2:2, 3:1, 4:3, 5:3, 6:3}
pc = {1:'D', 2:'D', 3:'N', 4:'N', 5:'D', 6:'N'}
T = 8000

# Check for missing data
for d in D:
    for j in J:
        if (d,j) not in dem and (d,j) in P:
            raise NotImplementedError("missing data: dem_{d,j}")
for k in K:
    if k not in pm or k not in pc:
        raise NotImplementedError("missing data: pm_k or pc_k")

prob = pulp.LpProblem("Personnel_Recruitment_Allocation", pulp.LpMinimize)

# Decision variables
x = {}
for k in K:
    for d in D:
        for j in J:
            if (k,j) in C and (d,j) in P:
                x[k,d,j] = pulp.LpVariable(f"x_{k}_{d}_{j}", lowBound=0, upBound=1500, cat=pulp.LpInteger)

# Deviation variables
d_neg_dj = {p: pulp.LpVariable(f"d_neg_{p[0]}_{p[1]}", lowBound=0) for p in P}
d_pos_dj = {p: pulp.LpVariable(f"d_pos_{p[0]}_{p[1]}", lowBound=0) for p in P}
d_neg_2 = pulp.LpVariable("d_neg_2", lowBound=0)
d_pos_2 = pulp.LpVariable("d_pos_2", lowBound=0)
d_neg_3 = pulp.LpVariable("d_neg_3", lowBound=0)
d_pos_3 = pulp.LpVariable("d_pos_3", lowBound=0)

# Constraints
# C1: Applicant availability
for k in K:
    terms = [x[k,d,j] for d in D for j in J if (k,j) in C and (d,j) in P]
    prob += pulp.lpSum(terms) <= a[k], f"C1_{k}"

# C2: Demand balance
for (d,j) in P:
    terms = [x[k,d,j] for k in K if (k,j) in C]
    prob += pulp.lpSum(terms) + d_neg_dj[(d,j)] - d_pos_dj[(d,j)] == dem[(d,j)], f"C2_{d}_{j}"

# C3: Preferred-major balance
terms_C3 = []
for k in K:
    for d in D:
        if (d, pm[k]) in P:
            terms_C3.append(x[k, d, pm[k]])
prob += pulp.lpSum(terms_C3) + d_neg_2 - d_pos_2 == T, "C3"

# C4: Preferred-city balance
terms_C4 = []
for k in K:
    for j in J:
        if (k,j) in C and (pc[k], j) in P:
            terms_C4.append(x[k, pc[k], j])
prob += pulp.lpSum(terms_C4) + d_neg_3 - d_pos_3 == T, "C4"

# Objective
prob += 10**6 * pulp.lpSum(d_neg_dj[p] for p in P) + 10**3 * d_neg_2 + d_neg_3, "Objective"

# Solve
prob.solve(pulp.PULP_CBC_CMD(msg=False, timeLimit=60))
print(f"STATUS={pulp.LpStatus[prob.status]} OBJECTIVE={pulp.value(prob.objective)}")
